css = '''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f8f8;color:#13262e;font:18px/1.7 system-ui,sans-serif}a{color:#086b88;text-underline-offset:4px}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #bd7800;outline-offset:4px}header{background:#081d2a;color:white;padding:20px}header nav{max-width:1080px;margin:auto;display:flex;gap:22px;flex-wrap:wrap}header a{color:#a7e9f4}main{max-width:1000px;margin:auto;padding:36px 22px}h1,h2{font-family:Georgia,serif;line-height:1.15}h1{font-size:clamp(2.4rem,7vw,4.2rem);max-width:18ch;margin:18px 0}h2{font-size:clamp(1.65rem,4vw,2.2rem)}h3{font-size:1.2rem}.eyebrow{color:#086b88;font-size:.9rem;letter-spacing:.08em;font-weight:750}.lead{font-size:1.2rem;max-width:65ch}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}button,.button{font:inherit;display:inline-block;padding:12px 18px;background:#103448;color:white;border:0;border-radius:10px;cursor:pointer;min-height:48px;text-decoration:none}.secondary{background:white;color:#103448;border:1px solid #9eb7c0}section,.panel{padding:24px clamp(18px,4vw,32px);background:white;border:1px solid #cfdee2;border-radius:16px;margin:24px 0;scroll-margin-top:22px}.review{font-size:1rem;background:#e8f4f7;border-left:4px solid #147e9e;padding:18px 22px}.review p{margin:4px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.grid .panel{margin:0}.checklist{list-style:none;padding:0}.checklist li{border-bottom:1px solid #d5e3e6}.checklist label{display:flex;gap:12px;padding:14px 0;align-items:flex-start;cursor:pointer}.checklist input{width:20px;height:20px;flex-shrink:0;margin-top:6px}.urgent{border-left:5px solid #9a3b24;background:#fff4ef}.small{font-size:1rem;color:#435d67}.sources a{overflow-wrap:anywhere}.sources li{margin:10px 0}img{max-width:100%;height:auto}.poster{max-width:260px}.print-only{display:none}footer{border-top:1px solid #bacdd3;padding:24px 0;margin-top:40px}.breadcrumb{font-size:1rem}@media(max-width:650px){.grid{grid-template-columns:1fr}main{padding:24px 16px}section{padding:20px}header nav{gap:14px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{header,.actions,.no-print,.poster{display:none!important}body{background:white;color:black;font-size:11pt}main{max-width:none;padding:0}section,.panel{padding:8px 0;border:0;margin:12px 0;break-inside:avoid}h1{font-size:25pt;max-width:none}h2{font-size:17pt}.review{padding:8px;border:1px solid #aaa;font-size:10pt}.grid{display:block}.print-only{display:block}.checklist label{padding:6px 0}a{color:black}.sources{font-size:9pt}@page{size:letter;margin:16mm}}
'''
(ROOT/'visit-guides.css').write_text(css)
(ROOT/'visit-guides.js').write_text("document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));\n")

NCI_TEST='https://www.cancer.gov/about-cancer/causes-prevention/genetics/genetic-testing-fact-sheet'
NCI_CDH='https://www.cancer.gov/publications/pdq/information-summaries/genetics/hereditary-diffuse-gastric-cancer-hp-pdq'
CDH='https://medlineplus.gov/genetics/gene/cdh1/'
CDC_RETURN='https://www.cdc.gov/heads-up/guidelines/returning-to-sports.html'
CDC_SIGNS='https://www.cdc.gov/heads-up/signs-symptoms/index.html'
NIAMS='https://www.niams.nih.gov/health-topics/sports-injuries'
NIMH='https://www.nimh.nih.gov/health/publications/depression'
PATH='https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/pathology-reports-fact-sheet'
QUESTIONS='https://www.cancer.gov/about-cancer/coping/questions'

def section(title,body,cls=''):
    return f'<section class="{cls}"><h2>{title}</h2>{body}</section>'
def p(s): return '<p>'+s+'</p>'
def checks(items):
    return '<ul class="checklist">'+''.join(f'<li><label><input type="checkbox"><span>{i}</span></label></li>' for i in items)+'</ul>'
def page(slug,lang,title,lead,body,sources):
    es=lang=='es'; name=slug+('-es' if es else '')+'.html'; other=slug+('' if es else '-es')+'.html'
    review=('Resumen educativo preparado con asistencia de IA a partir de las fuentes indicadas. No se ha documentado una revisión clínica individual de esta guía. La aprobación de la colección de carteles no se extiende a esta página.' if es else 'Educational summary prepared with AI assistance from the linked sources. Individual clinical review of this guide has not yet been documented. Approval of the poster collection does not extend to this page.')
    source_list=''.join(f'<li><a href="{u}">{escape(t)}</a></li>' for t,u in sources)
    content=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Alex Ehsan, MD, PhD</title><meta name="description" content="{escape(lead,quote=True)}"><link rel="canonical" href="https://dralexehsan.com/{name}"><link rel="alternate" hreflang="{'en' if es else 'es'}" href="https://dralexehsan.com/{other}"><link rel="stylesheet" href="visit-guides.css"></head><body><header><nav aria-label="{'Navegación' if es else 'Navigation'}"><a href="index.html">Alex Ehsan, MD, PhD</a><a href="visit-guides{'-es' if es else ''}.html">{'Preparar mi consulta' if es else 'Prepare for a visit'}</a><a href="{other}" lang="{'en' if es else 'es'}">{'English' if es else 'Español'}</a></nav></header><main><p class="eyebrow">{'EDUCACIÓN GRATUITA' if es else 'FREE PATIENT EDUCATION'}</p><h1>{title}</h1><p class="lead">{lead}</p><div class="actions"><a class="button" href="#questions">{'Preguntas para mi equipo' if es else 'Questions for my team'}</a><button class="secondary" data-print type="button">{'Imprimir guía y preguntas' if es else 'Print guide and questions'}</button></div><aside class="review"><p><strong>{'Preparación editorial' if es else 'Editorial preparation'}</strong> · {'28 de septiembre de 2026' if es else DATE}</p><p>{review}</p></aside>{body}<section class="sources"><h2>{'Fuentes y lecturas adicionales' if es else 'Sources and further reading'}</h2><ul>{source_list}</ul><p class="small">{'Fuentes consultadas el 28 de septiembre de 2026. Sus fechas de revisión varían.' if es else 'Sources consulted September 28, 2026. Source review dates vary.'}</p></section><footer><p>{'Solo información educativa. No sustituye la evaluación de su equipo médico.' if es else 'Educational only. This does not replace assessment by your own healthcare team.'}</p><p class="small">{'Las casillas no se envían ni se guardan por esta página. No ingrese datos personales. Puede imprimir y escribir sus notas en papel.' if es else 'This page does not submit or save checklist selections. Do not enter personal information. Print and add your notes on paper.'}</p><p class="print-only">dralexehsan.com/{name}</p></footer></main><script src="visit-guides.js" defer></script></body></html>'''
    (ROOT/name).write_text(content)

for lang in ['en','es']:
    es=lang=='es'
    if not es:
        body=section('What CDH1 means',p('CDH1 helps make E-cadherin, a protein that helps cells stay connected. Everyone has this gene. The exact genetic change and its classification determine what a result may mean.'))
        body+=section('What changes the discussion',p('Certain inherited pathogenic or likely pathogenic variants are associated with diffuse stomach cancer and lobular breast cancer. A finding in tumor tissue does not by itself establish an inherited condition. A variant of uncertain significance, or VUS, is not a confirmed harmful result and should not alone determine preventive surgery.'))
        body+=section('The next conversation',p('For a confirmed inherited harmful variant, a specialist team can discuss expert stomach surveillance, risk-reducing surgery, breast screening when relevant, and nutrition. The balance depends on the variant, age, family history and individual circumstances. This guide cannot calculate personal risk or choose a screening schedule.'))
        items=['What is the exact variant and its current classification?','Was this an inherited-risk test or a tumor test? Is confirmation needed?','How does my family history change the recommendations?','Which surveillance and risk-reduction options apply to me?','Who will explain potential benefits, limitations and long-term effects?','Should relatives discuss testing, and who will track reclassification?']
        body+='<section id="questions"><h2>Prepare for your genetics appointment</h2>'+p('Bring the laboratory report and a family history with cancer types and ages at diagnosis to your clinician. Select the questions you want to discuss.')+checks(items)+'</section>'
        body+=section('A conversation with family',p('You can ask your genetics team for a family letter that explains the confirmed finding and where relatives can seek counseling. Share only information you choose to share.'))
        body+=section('When not to wait',p('Vomiting blood, black stools with weakness or fainting, or another possible emergency needs urgent medical attention. Do not wait for genetic counseling or a website reply.'),'urgent')
        title='CDH1 and your next conversation'; lead='Understand the result, keep uncertainty in perspective, and prepare questions for a genetics professional.'
    else:
        body=section('Qué significa CDH1',p('CDH1 ayuda a producir E-cadherina, una proteína que mantiene unidas las células. Todas las personas tienen este gen. El cambio genético exacto y su clasificación determinan el significado del resultado.'))
        body+=section('Qué cambia la conversación',p('Ciertas variantes hereditarias patógenas o probablemente patógenas se asocian con cáncer gástrico difuso y cáncer de mama lobulillar. Un hallazgo en el tumor no confirma por sí solo una condición hereditaria. Una variante de significado incierto, o VUS, no es un resultado dañino confirmado y no debe determinar por sí sola una cirugía preventiva.'))
        body+=section('La próxima conversación',p('Ante una variante hereditaria dañina confirmada, un equipo especializado puede explicar la vigilancia gástrica especializada, la cirugía para reducir el riesgo, la detección de cáncer de mama cuando corresponda y la nutrición. Las decisiones dependen de la variante, la edad, los antecedentes familiares y las circunstancias personales. Esta guía no calcula el riesgo individual ni elige un calendario de pruebas.'))
        items=['¿Cuál es la variante exacta y su clasificación actual?','¿Fue una prueba de riesgo hereditario o del tumor? ¿Necesita confirmación?','¿Cómo influyen mis antecedentes familiares?','¿Qué opciones de vigilancia y reducción del riesgo se aplican a mí?','¿Quién explicará los beneficios, las limitaciones y los efectos a largo plazo?','¿Deben mis familiares consultar sobre pruebas? ¿Quién seguirá los cambios de clasificación?']
        body+='<section id="questions"><h2>Prepare su consulta de genética</h2>'+p('Lleve el informe del laboratorio y los antecedentes familiares con los tipos de cáncer y las edades al diagnóstico. Seleccione las preguntas que desea comentar.')+checks(items)+'</section>'
        body+=section('Hablar con la familia',p('Puede pedir a su equipo de genética una carta que explique el hallazgo confirmado y cómo pueden sus familiares obtener asesoramiento. Comparta solo lo que usted decida.'))
        body+=section('Cuándo no debe esperar',p('Vomitar sangre, tener heces negras con debilidad o desmayo, u otra posible emergencia requiere atención urgente. No espere una consulta de genética ni una respuesta por internet.'),'urgent')
        title='CDH1 y su próxima conversación'; lead='Comprenda el resultado y prepare preguntas para un profesional de genética, sin confundir incertidumbre con un diagnóstico.'
    page('cdh1-guide',lang,title,lead,body,[('MedlinePlus Genetics · CDH1',CDH),('NCI · Hereditary diffuse gastric cancer',NCI_CDH),('NCI · Genetic testing for inherited cancer risk',NCI_TEST)])

    if not es:
        title='Prepare for your cancer visit';lead='A clear diagnosis, a treatment goal, and questions you can take into the room.'
        body=section('Start with the report',p('A pathology report describes the tissue examined and the diagnosis. Grade describes how abnormal the cells look. Stage describes the extent of cancer. Biomarker results may guide treatment, and some results arrive later as an addendum. Ask your team which findings are final and which are still pending.'))
        body+=section('What changes the plan',p('The cancer type, extent, biology, prior treatment, overall health and your priorities shape the discussion. Ask your clinician to explain the goal before comparing options. A list of drugs is not an individualized treatment sequence.'))
        body+='<section id="questions"><h2>Questions for your next visit</h2>'+checks(['What is the exact diagnosis, and which results are still pending?','What is the stage, and what does it mean in my situation?','Which biomarkers or inherited-risk tests are relevant?','Is the goal cure, control, symptom relief, or a combination?','What are the benefits, risks and alternatives, including appropriate trials?','How will we know whether treatment is helping?','Who should I call about symptoms, including after hours?'])+'</section>'
        body+=section('Bring what helps',p('Bring your medication list, outside reports, and your three most important questions. Ask whether a support person or interpreter can join. Request a written summary of the agreed next step.'))
        body+=section('A learning example',p('Hypothetical example, not a patient story. Two reports can name the same organ but contain different tumor types or biomarkers. A useful question is “Which finding in my report changes the options?”'))
        body+=section('If symptoms cannot wait',p('Follow your treatment team’s urgent-symptom instructions. Call 911 for severe breathing difficulty, new stroke symptoms or another life-threatening emergency.'),'urgent')
    else:
        title='Prepare su consulta de cáncer';lead='Comprenda el diagnóstico, la meta del tratamiento y las preguntas que desea llevar a la consulta.'
        body=section('Empiece por el informe',p('El informe de patología describe el tejido examinado y el diagnóstico. El grado indica qué tan anormales parecen las células. El estadio describe la extensión del cáncer. Los biomarcadores pueden orientar el tratamiento, y algunos resultados llegan después en un informe adicional. Pregunte qué resultados son definitivos y cuáles siguen pendientes.'))
        body+=section('Qué cambia el plan',p('El tipo, la extensión y la biología del cáncer, los tratamientos previos, la salud general y sus prioridades orientan la conversación. Pida que le expliquen la meta antes de comparar opciones. Una lista de medicamentos no es una secuencia de tratamiento individualizada.'))
        body+='<section id="questions"><h2>Preguntas para su próxima consulta</h2>'+checks(['¿Cuál es el diagnóstico exacto y qué resultados faltan?','¿Cuál es el estadio y qué significa en mi situación?','¿Qué biomarcadores o pruebas de riesgo hereditario son relevantes?','¿La meta es curar, controlar, aliviar síntomas o una combinación?','¿Cuáles son los beneficios, riesgos y alternativas, incluidos ensayos apropiados?','¿Cómo sabremos si el tratamiento ayuda?','¿A quién debo llamar por síntomas, incluso fuera de horario?'])+'</section>'
        body+=section('Qué llevar',p('Lleve su lista de medicamentos, informes externos y sus tres preguntas principales. Pregunte si puede participar una persona de apoyo o un intérprete. Solicite un resumen escrito del siguiente paso acordado.'))
        body+=section('Un ejemplo para aprender',p('Ejemplo hipotético, no una historia de un paciente. Dos informes pueden mencionar el mismo órgano pero diferentes tipos de tumor o biomarcadores. Una pregunta útil es “¿Qué hallazgo de mi informe cambia las opciones?”'))
        body+=section('Si los síntomas no pueden esperar',p('Siga las instrucciones de su equipo sobre síntomas urgentes. Llame al 911 ante dificultad respiratoria grave, nuevos signos de accidente cerebrovascular u otra emergencia potencialmente mortal.'),'urgent')
    page('cancer-visit-guide',lang,title,lead,body,[('NCI · Surgical pathology reports',PATH),('NCI · Questions to ask about cancer',QUESTIONS)])

    if not es:
        title='Football. Protect your next chapter.';lead='A learning package for student athletes, parents and coaches. Prevention, recovery and confidence belong in the same conversation.'
        body=section('Before practice',p('Build training gradually, allow recovery, use appropriate equipment and learn sound technique. Tell the athletic trainer about prior injuries or new symptoms. Injury risk can be reduced but never eliminated.'))
        body+=section('After an injury',p('Stop when an injury causes severe pain, major swelling, a deformed joint or inability to bear weight, and seek prompt assessment. Rehabilitation and return decisions depend on the diagnosis. Do not use a teammate’s recovery calendar as your own.'))
        body+=section('Suspected concussion',p('Remove the athlete from play and arrange medical assessment. No return that day. After a concussion, return to sport requires healthcare approval and a supervised progression. Each CDC return step usually takes at least 24 hours. If symptoms return, stop and contact the clinician.'),'urgent')
        body+=section('Emergency signs',p('After a head injury, call 911 for seizures, repeated vomiting, worsening headache, slurred speech, weakness or difficulty waking. For suspected neck or spine injury, do not move the athlete unless needed for immediate lifesaving care. Activate emergency services.'),'urgent')
        body+=section('Confidence is part of recovery',p('Discuss fear of reinjury, sleep, mood and feeling disconnected from the team. Persistent distress deserves professional support. In the U.S., call or text 988 for a mental health crisis; call 911 for immediate danger.'))
        body+='<section id="questions"><h2>Build the plan with your team</h2>'+checks(['What is the diagnosis, and which activities should I avoid?','What can I safely do while recovering?','Which strength, movement and sport-specific goals must I meet?','Who provides clearance, and how will school and coaches receive the plan?','What symptoms mean I should stop or seek urgent care?','Who can help with confidence, mood or fear of reinjury?'])+'</section>'
        story='Read Matthew’s complete story'; posters='Browse football posters'; full='Open the football injury guide'; tips='For coaches and parents'; tiptext='Before the next practice, confirm who receives injury reports, where the emergency plan is kept, and how families receive medical follow-up instructions.'
    else:
        title='Fútbol americano. Proteja su futuro.';lead='Una guía para estudiantes deportistas, familias y entrenadores. La prevención, la recuperación y la confianza forman parte de la misma conversación.'
        body=section('Antes de entrenar',p('Aumente el entrenamiento gradualmente, permita la recuperación, use el equipo adecuado y aprenda una técnica correcta. Informe al profesional de medicina deportiva sobre lesiones previas o síntomas nuevos. El riesgo puede reducirse, pero no eliminarse.'))
        body+=section('Después de una lesión',p('Deténgase y busque evaluación pronta ante dolor intenso, hinchazón importante, deformidad de una articulación o incapacidad para apoyar el peso. La rehabilitación y el regreso dependen del diagnóstico. No use el calendario de recuperación de un compañero como si fuera el suyo.'))
        body+=section('Posible conmoción cerebral',p('Retire al deportista del juego y busque evaluación médica. No debe regresar ese día. Tras una conmoción, se necesita aprobación médica y una progresión supervisada. Cada etapa de los CDC suele requerir al menos 24 horas. Si vuelven los síntomas, deténgase y contacte al profesional.'),'urgent')
        body+=section('Señales de emergencia',p('Tras un golpe en la cabeza, llame al 911 ante convulsiones, vómitos repetidos, dolor de cabeza que empeora, habla arrastrada, debilidad o dificultad para despertar. Si se sospecha una lesión del cuello o columna, no mueva al deportista salvo para salvarle la vida de inmediato. Active los servicios de emergencia.'),'urgent')
        body+=section('La confianza también se recupera',p('Hable del miedo a lesionarse de nuevo, el sueño, el ánimo y la desconexión del equipo. El malestar persistente merece apoyo profesional. En Estados Unidos, llame o envíe un mensaje al 988 ante una crisis de salud mental; llame al 911 ante peligro inmediato.'))
        body+='<section id="questions"><h2>Prepare el plan con su equipo</h2>'+checks(['¿Cuál es el diagnóstico y qué actividades debo evitar?','¿Qué puedo hacer de forma segura durante la recuperación?','¿Qué metas de fuerza, movimiento y deporte debo alcanzar?','¿Quién autoriza el regreso y cómo recibirán el plan la escuela y los entrenadores?','¿Qué síntomas indican que debo parar o buscar atención urgente?','¿Quién puede ayudarme con la confianza, el ánimo o el miedo a otra lesión?'])+'</section>'
        story='Lea la historia completa de Matthew (inglés)';posters='Vea los carteles de fútbol americano (inglés)';full='Abra la guía de lesiones de fútbol americano (inglés)';tips='Para entrenadores y familias';tiptext='Antes de la próxima práctica, confirmen quién recibe los avisos de lesiones, dónde está el plan de emergencia y cómo reciben las familias las instrucciones de seguimiento médico.'
    body+=section(tips,p(tiptext))
    body+=section('Keeping Young Athletes in the Game',p(('Founded by Matthew Ehsan, a Texas Tech kinesiology student who became one of the captains of the McKinney varsity football team. His story is a personal perspective, not clinical advice.' if not es else 'Fundado por Matthew Ehsan, estudiante de kinesiología de Texas Tech que llegó a ser uno de los capitanes del equipo de fútbol americano de McKinney. Su historia es una perspectiva personal, no consejo clínico.'))+f'<p><a href="athlete-injury-center.html#matthews-story">{story}</a></p><p><a href="athlete-injury-center.html#american-football">{full}</a></p><p><a href="sport-posters.html?sport=american-football">{posters}</a></p><a class="no-print" href="posters/sport-american-football.webp"><img class="poster" src="posters/sport-american-football.webp" width="1024" height="1536" loading="lazy" alt="American football safety poster in English"></a>')
    page('football-learning-guide',lang,title,lead,body,[('NIAMS · Sports injuries',NIAMS),('CDC HEADS UP · Return to sports',CDC_RETURN),('CDC HEADS UP · Concussion danger signs',CDC_SIGNS),('NIMH · Depression',NIMH)])

for lang in ['en','es']:
    es=lang=='es';suffix='-es' if es else ''
    title='Prepare su próxima consulta' if es else 'Prepare for your next visit'
    cards=[('CDH1 y genética' if es else 'CDH1 and genetics','cdh1-guide'),('Su consulta de cáncer' if es else 'Your cancer visit','cancer-visit-guide'),('Fútbol americano y recuperación' if es else 'Football and recovery','football-learning-guide')]
    body='<div class="grid">'+''.join(f'<article class="panel"><h2>{t}</h2><a href="{slug}{suffix}.html">'+('Leer la guía y preparar preguntas' if es else 'Read the guide and prepare questions')+'</a></article>' for t,slug in cards)+'</div>'
    page('visit-guides',lang,title,('Guías gratuitas con preguntas imprimibles y fuentes para continuar aprendiendo.' if es else 'Free guides with printable questions and sources for further learning.'),body,[])
    f=ROOT/f'visit-guides{suffix}.html';s=f.read_text();s=s.replace('href="#questions"',f'href="cancer-visit-guide{suffix}.html#questions"');f.write_text(s)

# Keep the established homepage palette, search controls and underlying library intact.
path=ROOT/'index.html';s=path.read_text()
script=re.search(r'<script>(.*?)</script>',s,re.S)
if script:
    js=script.group(1)
    js+='''\nconst initialQuery=new URLSearchParams(location.search);if(initialQuery.has('q')||initialQuery.has('category'))chooseCategory(initialQuery.get('category')||'all',initialQuery.get('q')||'');\n'''
    (ROOT/'medical-library.js').write_text(js)
    s=s[:script.start()]+'<script src="medical-library.js" defer></script>'+s[script.end():]
doc=html.document_fromstring(s)
def el(markup):return html.fragment_fromstring(markup)
def byid(i):return doc.get_element_by_id(i)
def serialize(e):return html.tostring(e,encoding='unicode')

search=doc.xpath('//section[contains(@class,"home-search")]')[0]
routes='''<section class="entry-paths" aria-label="Choose your health topic"><div class="shell"><div class="route-grid"><a href="cancer-visit-guide.html"><strong>Cancer and blood disorders</strong><span>Understand a diagnosis. Prepare for your visit.</span></a><a href="genetics.html"><strong>Genes and genetic testing</strong><span>Start with CDH1 or search a gene.</span></a><a href="football-learning-guide.html"><strong>Athletes and recovery</strong><span>Prevention, rehabilitation and confidence.</span></a><a href="#everyday-health"><strong>Everyday and mental health</strong><span>Find a clear starting point.</span></a></div></div></section>'''
search.addnext(el(routes))
# Remove the older duplicate category strip; its controls remain available in search.
for node in doc.xpath('//section[@aria-label="Explore health topics"]'):node.getparent().remove(node)
story=byid('matthew-athlete-story')
story.clear();story.set('class','section');story.set('id','matthew-athlete-story')
story.append(el('''<div class="shell"><article class="matthew-letter"><p class="eyebrow">Keeping Young Athletes in the Game</p><h2>My comeback has a purpose</h2><p><strong>Matthew Ehsan · Student founder · Texas Tech kinesiology</strong></p><p>I started with basketball, then moved into track and field, where I broke a few records. I later found strength in powerlifting and became one of the captains of my varsity football team. Rehabilitation for a shoulder injury taught me how much recovery depends on learning to move and train properly. I did not have shoulder surgery. I also love playing piano and continue to live with a serious pinky injury. Surgery will be required. These experiences helped shape my purpose. Now I am studying kinesiology with the goal of becoming a physician and helping other student athletes understand injury prevention, rehabilitation, and the value of caring for their future.</p><div class="actions"><a class="btn btn-primary" href="athlete-injury-center.html#matthews-story">Read Matthew’s full letter</a><a class="btn btn-ghost" href="football-learning-guide.html">Explore the football learning package</a></div></article></div>'''))
# Move the long mission statement to the About area, retaining the purpose quote near the top.
